INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 1: 방송국소개', 'broadcast-sample-1', '제주한라대학교 방송국 메뉴의 방송국소개 섹션 샘플 기사입니다. 메뉴 이동과 상세 페이지 연결, 편집 워크플로우 점검을 위해 작성되었습니다.', 1, c.category_id, 'published', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=1200&q=80', 'ysz5S6PUM-U', 'normal', datetime('now','-37 days'), 101 FROM categories c WHERE c.slug = 'broadcast/방송국소개';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 2: CHEBS뉴스', 'broadcast-sample-2', '제주한라대학교 방송국 메뉴의 CHEBS뉴스 섹션 샘플 기사입니다. 메뉴 이동과 상세 페이지 연결, 편집 워크플로우 점검을 위해 작성되었습니다.', 2, c.category_id, 'published', 'https://images.unsplash.com/photo-1489515217757-5fd1be406fef?auto=format&fit=crop&w=1200&q=80', '3JZ_D3ELwOQ', 'normal', datetime('now','-36 days'), 102 FROM categories c WHERE c.slug = 'broadcast/CHEBS뉴스';
INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 방송국 샘플 기사 3: 제작프로그램', 'broadcast-sample-3', '제주한라대학교 방송국 메뉴의 제작프로그램 섹션 샘플 기사입니다. 메뉴 이동과 상세 페이지 연결, 편집 워크플로우 점검을 위해 작성되었습니다.', 3, c.category_id, 'published', 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=1200&q=80', 'M7lc1UVf-VE', 'normal', datetime('now','-35 days'), 103 FROM categories c WHERE c.slug = 'broadcast/제작프로그램';
