INSERT OR IGNORE INTO articles (title, slug, content, author_id, category_id, status, featured_image_url, youtube_embed_id, article_type, published_at, view_count) SELECT '제주한라대학교 에세이 샘플 기사 6: 나만의 생각 정리', 'essay-sample-6', '제주한라대학교 에세이 메뉴의 나만의 생각 정리 섹션 샘플 기사입니다. 메뉴 이동과 상세 페이지 연결, 편집 워크플로우 점검을 위해 작성되었습니다.', 1, c.category_id, 'published', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=1200&q=80', NULL, 'normal', datetime('now','-18 days'), 106 FROM categories c WHERE c.slug = 'essay/나만의 생각 정리';
